"""Reviewed Owner interface knowledge. Update paths/steps with their UI changes.

Deterministic application help is deliberately independent of provider availability.
No account data, financial formulas or write execution belongs in this registry.
"""
import re
from copilot.authorization import require
from copilot.security import AccessDenied

HELP = [
 dict(module='Business Overview', path='/dashboard', permission='view_dashboard', match=r'dashboard|business overview|reporting period', steps='Open Dashboard (Business Overview). Set Start, End and Granularity, then Apply. Use the reporting controls for the recorded period; sandbox disclosures remain applicable.', limitations='Recorded results can include synthetic and simulated activity; revenue is not cash balance.'),
 dict(module='Bulk POS Import', path='/merchant-transactions/import', permission='bulk_import', match=r'import|upload|map.*column|revenue.*expense.*report|expense.*report|rejected', steps='Open Merchant Transactions → Bulk POS Import. Upload CSV or XLSX files, select worksheets, confirm the Revenue or Expense report profile, and review detected data when requested. Map each selected worksheet independently. Validate, review errors, duplicates, reconciliation and combined Preview, then explicitly confirm Import. For rejected rows, correct the source or mapping and validate again.', limitations='Revenue records sales; Expense records costs. Follow the selected profile and canonical sign validation. Formula-derived financial values need trustworthy source data; ambiguous boundaries require review. No foreign-exchange conversion. Preview never saves transactions.'),
 dict(module='Single Transaction', path='/merchant-transactions/single', permission='create_transactions', match=r'record.*expense|record.*transaction|manual|encode', steps='Open Merchant Transactions → Single Transaction. Select the transaction type, enter date, amount, currency, payment method, status and reference using the form, then review validation and save.', limitations='Use the merchant currency and the displayed sign rules. Required and duplicate checks still apply.'),
 dict(module='Transaction History', path='/merchant-transactions/history', permission='view_transactions', match=r'transaction history|ledger|recorded transaction', steps='Open Merchant Transactions → Transaction History. Filter the saved records and review transaction details and provenance.', limitations='Only authorized merchant records are visible; importing a preview does not add history.'),
 dict(module='Transaction Settings', path='/merchant-transactions/settings', permission='manage_transactions', match=r'currency|timezone|date format|transaction settings|payment.*translation', steps='Open Merchant Transactions → Transaction Settings. Base Currency and Timezone are read-only. Choose Preferred Date Format and Default Transaction Status, then Save Settings. System Admin configures merchant information through Merchant Management. Unknown payment labels can be reviewed in Bulk POS Import; saved translations and templates remain available there.', limitations='No Owner-side currency or timezone editing. No FX conversion or historical currency migration. Date display preference does not change source date parsing.'),
 dict(module='Data Quality & Monitoring', path='/merchant-transactions/data-quality', permission='view_quality_monitoring', match=r'data quality|monitoring|duplicate|validation rule', steps='Open Merchant Transactions → Data Quality & Monitoring. Use Overview, Import History and Alerts. Expand How Metrics Are Calculated for definitions. Open an import summary to inspect validation and reconciliation. Alert actions require their separate delegated permissions.', limitations='Checks cannot be disabled here. Status changes do not bypass validation; matching runs and alerts use paginated monitoring results.'),
 dict(module='Digital Payments', path='/payment-sandbox', permission='simulate_payments', match=r'simulat|payment|generate.*qr|qr for|pay link|tap pay', steps='Open Digital Payments. Select the sandbox payment method and amount or catalog items. Review and explicitly confirm the simulated request, then use the existing payment simulation controls to record a simulated payment.', limitations='No real money moves. A request is not a completed sale. This chat guidance creates no payment or QR.'),
 dict(module='Cash Flow', path='/cash-flow', permission='view_forecasts', match=r'cash.flow|cash buffer|forecast', steps='Open Dashboard -> Cash Flow to review the existing balance forecast, cash buffer and rule alerts. The authorized /cash-flow link remains available for accounts without Dashboard access. Check the displayed method and assumptions.', limitations='Projected balances are estimates, not verified bank settlement or guaranteed future cash.'),
 dict(module='RBF Calculator', path='/financing/rbf', permission='view_financing', match=r'rbf|revenue.based|borrow', steps='Open Financing → RBF Calculator. Adjust the requested advance with the existing calculator controls and review fee, revenue share, repayment and eligibility information.', limitations='Indicative simulation only. The lender decides credit; a quote does not establish an approved limit.'),
 dict(module='Business Growth', path='/dashboard', permission='view_assessment', match=r'progression|milestone|journey', steps='Open Financing -> Overview for the compact maturity summary when authorized. Dashboard -> Overview shows the existing incentive milestone. Use the header notification bell for business alerts. The detailed maturity view and five-step financing journey are not visible dashboard tabs.', limitations='Existing maturity thresholds and gates are provisional POC rules. Improving a dimension does not guarantee advancement. Incentive milestones are not guaranteed rewards or credit approval.'),
 dict(module='Financing Applications', path='/financing/applications', permission='view_applications', match=r'application|financing draft|submit.*financ', steps='Open Financing → Applications. Select New Financing Application, enter the requested amount and Bank for Review, then Save Draft. Select the appropriate Bank. The Owner must authorize applications sharing in Bank Authorization before proposing submission. Review the proposed packet and explicitly confirm the existing submission workflow.', limitations='Staff require delegated draft permissions and see their own drafts. Only the authorized Owner submits; no loan approval or disbursement occurs. This chat does not submit an application.'),
 dict(module='Bank Authorization', path='/consents', permission='manage_consents', match=r'authoriz.*bank|bank.*authoriz|consent|bank access', steps='Open Bank Authorization in the Owner sidebar. Select Authorize Bank, choose an eligible assigned active Bank, purpose, expiration and data categories, then confirm and Authorize Bank. Review or revoke existing grants on that page.', limitations='Owner only. No unrelated Bank is listed; an empty recipient list requires an eligible assignment. Consent is category-specific, expires, and can be revoked. This chat cannot grant access.'),
 dict(module='Own-business User Management', path='/owner/users', permission='manage_merchant_staff', match=r'staff|delegat|user management|permission', steps='Open Own-business User Management in the Owner sidebar. In Staff Access, select Manage Access for an assigned staff account, review its merchant-specific grants and explicitly Save Changes.', limitations='Owner delegation is bounded by existing Staff permissions. It grants no System Admin powers or unrelated merchant access. This chat cannot change permissions.'),
 dict(module='Financing Overview', path='/financing', permission='view_financing', match=r'financing|finance', steps='Open Financing → Overview to review the existing indicative financing matches and reasons. Use RBF Calculator or Applications for their separate workflows.', limitations='Matches are advisory, subject to available business evidence and lender decisions.'),
]

def answer(p,mid,text):
    """Return grounded explain-only help or None. Live authorization precedes content."""
    if re.search(r'how can i progress toward financing',text,re.I):return None
    if not re.search(r'how (?:do|can|to)\b|where|help|guide|steps|difference|why.*(?:reject|import)|what does.*(?:monitor|quality)',text,re.I):return None
    for entry in HELP:
        if not re.search(entry['match'],text,re.I):continue
        require(p,entry['permission'],mid)
        # Non-authenticated internal principals must also respect role boundaries.
        if p.role not in ('owner','staff'):raise AccessDenied('Owner application guidance is not available to this role')
        return {'reply':entry['module']+'\n'+entry['steps']+'\n'+entry['limitations']+'\nNavigation: '+entry['path'],
                'tools_used':[], 'mode':'rule_engine','classification':'APPLICATION_GUIDANCE','evidence':[],
                'data':{'help_module':entry['module'],'navigation_path':entry['path']},'connection_status':'deterministic'}
    return None
